const float PALETTE_TIME_SCALE = 1.0;
const float SINE_TIME_SCALE = 1.0;
const float SINE_FREQ = 8.0;
const float GRID_FACTOR = 1.5;
const float ITERATIONS = 4.0;


// Colorpalette

vec3 palette( in float t )
{
    vec3 a = vec3(0.5, 0.5, 0.5);
    vec3 b = vec3(0.5, 0.5, 0.5);
    vec3 c = vec3(1.0, 1.0, 1.0);
    vec3 d = vec3(0.0, 0.33, 0.66);
    return a + b*cos( 6.283185*(c*t+d) );
}


// Smooth Boolean Operations

float opSmoothUnion( float d1, float d2, float k )
{
    float h = clamp( 0.5 + 0.5*(d2-d1)/k, 0.0, 1.0 );
    return mix( d2, d1, h ) - k*h*(1.0-h);
}


// SDFs

float sdCircle( vec2 p, float s )
{
  return length(p)-s;
}

float sdBox( in vec2 p, in vec2 b )
{
    vec2 d = abs(p)-b;
    return length(max(d,0.0)) + min(max(d.x,d.y),0.0);
}


// Combine primitive SDFs

float sdfMap( vec2 p ) {
    float radius = 0.5 / GRID_FACTOR;
    float circle = sdCircle(p, radius);
    float square = sdBox(p, vec2(0.3));
    return opSmoothUnion(circle, square, 0.01);

}


// Main

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalized pixel coordinates and fix stretched pixels (from -1 to 1)
    vec2 UV = (fragCoord * 2.0 - iResolution.xy) / iResolution.y;
    float globalDistance = length(UV);

    vec2 gridCellUV = UV;
    vec3 finalColor = vec3(0.0);

    for(float i = 0.0; i < ITERATIONS; i++) {

        // fract is like modulo 1 leaving range [0.0, 1.0) creating repeating grid; subtracting 0.5 so it's centered
        gridCellUV = fract(gridCellUV * GRID_FACTOR) - 0.5;

        // get signed distance to combined primitives
        float gridCellDistance = sdfMap(gridCellUV);

        // multiplies exponential to linear distance; negatives go exp to -inf, positives peak at f(1) (depending on global distance from center)
        gridCellDistance *= exp(-(globalDistance));

        // get color from palette based on GLOBAL distance to center, animated by time, shifted by iteration
        vec3 col = palette(iTime * PALETTE_TIME_SCALE + (i / ITERATIONS) + globalDistance);

        // sin repeats the value animated by time
        gridCellDistance = sin(iTime * SINE_TIME_SCALE + gridCellDistance * SINE_FREQ) / SINE_FREQ;

        // abs makes inside black too leaving a ring
        gridCellDistance = abs(gridCellDistance);
        // inverting colors and sharpening gradient leaving a subtle glow
        gridCellDistance = 0.01 / gridCellDistance;
        // increasing darker shades, leaving ligther shades normal
        gridCellDistance = pow(gridCellDistance, 1.5);

        finalColor += col * gridCellDistance;
    }

    // Output to screen
    fragColor = vec4(finalColor, 1.0);
}
